$GLOBALS['oz_options'] = array(); $GLOBALS['oz_transients'] = array(); $repo = new SettingsRepository(); $settings = new OzonDeliverySettings( $repo ); $encryption = new EncryptionService(); $cache = new OzonDeliveryTokenCache( $encryption ); $credentials = new OzonDeliveryCredentials( $repo, $encryption, $cache );
oz_assert( OzonDeliverySettings::CARRIER_KEY === 'ozon_delivery' && OzonDeliverySettings::SERVICE_KEY === 'ozon_delivery' && OzonDeliverySettings::TOKEN_SCOPE === array( 'delivery-api.all' ), 'stable keys and approved scope are required.' );
oz_assert( array_key_exists( OzonDeliverySettings::CLIENT_ID_KEY, $repo->defaults() ), 'SettingsRepository must compose Ozon defaults.' );
