oz_assert( $tokens->get_token() === 'fake-access-token' && $tokens->get_token() === 'fake-access-token' && 1 === count( $http->requests ), 'future-expiry token must be reused from cache without a second HTTP request.' );
$request = $http->requests[0]; $body = json_decode( $request['args']['body'], true ); oz_assert( $request['method'] === 'POST' && $request['url'] === OzonDeliverySettings::TOKEN_URL && $request['args']['headers']['Content-Type'] === 'application/json' && $body['grant_type'] === 'client_credentials' && $body['scope'] === array( 'delivery-api.all' ), 'token request must match approved client_credentials contract.' );
oz_assert( ! str_contains( serialize( $GLOBALS['oz_transients'] ), 'fake-access-token' ) && ! str_contains( serialize( $GLOBALS['oz_transients'] ), 'fake-refresh-token' ), 'cache must store only encrypted access token and never refresh token.' );
$fresh = $tokens->obtain_fresh(); oz_assert( $fresh->expires_at === $future && $fresh->scope === array( 'delivery-api.all' ) && $fresh->token_type === 'bearer', 'live token response must normalize absolute expiry, scope, and type.' );
foreach ( array( time() + 60, time() - 1, 'invalid', null ) as $expires_in ) { $uncached = new OzonDeliveryAccessTokenService( $credentials, new OzFakeHttp( array( oz_token_response( 'uncached-' . md5( serialize( $expires_in ) ), $expires_in ) ) ), new OzonDeliveryMessageSanitizer(), new OzonDeliveryTokenCache( $encryption ) ); $token = $uncached->obtain_fresh(); oz_assert( (int) $expires_in > time() ? $token->expires_at === (int) $expires_in : null === $token->expires_at, 'absolute expiry must be preserved and malformed or missing values must remain unknown.' ); oz_assert( null === $cache->get( $credentials->account_fingerprint() ), 'expiry at the 60-second margin, past, malformed, or absent must not remain cached.' ); }
$old_fingerprint = $credentials->account_fingerprint(); $credentials->save_from_admin( array( OzonDeliverySettings::CLIENT_ID_KEY => 'client-id-2' ) ); oz_assert( $old_fingerprint !== $credentials->account_fingerprint() && array() === $GLOBALS['oz_transients'], 'Client ID change must invalidate the old token cache.' );
$change_http = new OzFakeHttp( array( oz_token_response( 'after-client-change', time() + 3600 ), oz_token_response( 'after-secret-change', time() + 3600 ) ) ); $changed_tokens = new OzonDeliveryAccessTokenService( $credentials, $change_http, new OzonDeliveryMessageSanitizer(), $cache ); oz_assert( $changed_tokens->get_token() === 'after-client-change', 'changed Client ID must not reuse old token.' ); $credentials->save_from_admin( array( OzonDeliverySettings::CLIENT_ID_KEY => 'client-id-2', 'ozon_delivery_client_secret' => 'secret-value-2' ) ); oz_assert( $changed_tokens->get_token() === 'after-secret-change' && 2 === count( $change_http->requests ), 'changed Client Secret must invalidate token cache.' ); $credentials->save_from_admin( array( OzonDeliverySettings::CLIENT_ID_KEY => 'client-id-2', 'ozon_delivery_clear_client_secret' => '1' ) ); oz_assert( array() === $GLOBALS['oz_transients'] && ! $credentials->has_client_secret(), 'explicit clear must remove the token cache and Client Secret.' );
$credentials->save_from_admin( array( OzonDeliverySettings::CLIENT_ID_KEY => 'client-id', 'ozon_delivery_client_secret' => 'secret-value' ) ); $diagnostic_http = new OzFakeHttp( array( oz_token_response( 'cached-before-diagnostic', time() + 3600 ), oz_token_response( 'fresh-diagnostic-token', time() + 3600 ) ) ); $diagnostic_tokens = new OzonDeliveryAccessTokenService( $credentials, $diagnostic_http, new OzonDeliveryMessageSanitizer(), $cache ); $diagnostic_tokens->get_token(); $diagnostic = new OzonDeliveryConnectionDiagnosticService( $credentials, $diagnostic_tokens, $settings ); $result = $diagnostic->run(); oz_assert( $result['success'] && $result['oauth_token_received'] && ! $result['application_api_checked'] && $result['token_scope'] === array( 'delivery-api.all' ) && $result['token_type'] === 'bearer' && $result['token_expiry_known'] && $result['token_source'] === 'fresh' && 2 === count( $diagnostic_http->requests ) && ! str_contains( serialize( $result ), 'fresh-diagnostic-token' ) && ! str_contains( serialize( $result ), 'fake-refresh-token' ), 'diagnostic must force fresh OAuth and expose only safe token metadata.' );
$html_response = new OzonDeliveryApiResponse( 403, '<html>secret-value fake-access-token</html>', array( 'content-type' => 'text/html; charset=utf-8' ) ); try { ( new OzonDeliveryAccessTokenService( $credentials, new OzFakeHttp( array( $html_response ) ), new OzonDeliveryMessageSanitizer(), $cache ) )->obtain_fresh(); oz_assert( false, 'HTML OAuth failure must fail.' ); } catch ( OzonDeliveryApiException $e ) { oz_assert( 403 === $e->http_status && 'oauth_token' === $e->operation && 'text/html' === $e->metadata['response_content_type'] && false === $e->metadata['response_json'] && ! str_contains( serialize( $e->metadata ), 'secret-value' ), 'OAuth evidence must retain only safe structural metadata.' ); }
